        const ty = try schema.messageType("structtest.Scalars3");
        var msg = try ty.decode(wire);
        defer msg.deinit();
        return load(allocator, schema, &msg, ty);
    }

    pub fn load(allocator: std.mem.Allocator, schema: *const pbwire.Schema, msg: *const pbwire.Message, ty: pbwire.MessageType) !Structtest_Scalars3 {
        var out: Structtest_Scalars3 = .{};
        {
            const f = try ty.field("i32");
            out.i32 = @as(i32, @truncate(msg.getI64(f)));
        }
        {
            const f = try ty.field("i64");
            out.i64 = @intCast(msg.getI64(f));
        }
        {
            const f = try ty.field("u32");
            out.u32 = @intCast(msg.getI64(f));
        }
        {
            const f = try ty.field("u64");
            out.u64 = @bitCast(msg.getI64(f));
        }
        {
            const f = try ty.field("s32");
            out.s32 = @as(i32, @truncate(msg.getI64(f)));
        }
        {
            const f = try ty.field("s64");
            out.s64 = @intCast(msg.getI64(f));
        }
        {
            const f = try ty.field("fx32");
            out.fx32 = @intCast(msg.getI64(f));
        }
        {
            const f = try ty.field("fx64");
            out.fx64 = @bitCast(msg.getI64(f));
        }
        {
            const f = try ty.field("sfx32");
            out.sfx32 = @as(i32, @truncate(msg.getI64(f)));
        }
        {
            const f = try ty.field("sfx64");
            out.sfx64 = @intCast(msg.getI64(f));
        }
        {
            const f = try ty.field("f32");
            out.f32 = msg.getF32(f);
        }
        {
            const f = try ty.field("f64");
            out.f64 = msg.getF64(f);
        }
        {
            const f = try ty.field("flag");
            out.flag = msg.getBool(f);
        }
        {
            const f = try ty.field("str");
            out.str = (if (msg.getStr(f)) |s| try allocator.dupe(u8, s) else "");
        }
        {
            const f = try ty.field("color");
            out.color = @enumFromInt(msg.getI64(f));
        }
        {
            const f = try ty.field("inner");
            if (msg.getMessage(f)) |sub| {
                const sty = try schema.messageType("structtest.Inner3");
                out.inner = try Structtest_Inner3.load(allocator, schema, &sub, sty);
            }
        }
        {
            const f = try ty.field("nums");
            if (msg.value(f)) |v| {
                var xs = try allocator.alloc(i32, v.len());
                for (0..v.len()) |i| {
                    if (v.at(i)) |item| {
                        xs[i] = @as(i32, @truncate(item.asI64()));
                    }
                }
                out.nums = xs;
            }
        }
        {
            const f = try ty.field("tags");
            if (msg.value(f)) |v| {
                var xs = try allocator.alloc([]const u8, v.len());
                for (0..v.len()) |i| {
                    if (v.at(i)) |item| {
                        xs[i] = (if (item.asStr()) |s| try allocator.dupe(u8, s) else "");
                    }
                }
                out.tags = xs;
            }
        }
        {
            const f = try ty.field("inners");
            if (msg.value(f)) |v| {
                const sty = try schema.messageType("structtest.Inner3");
                var xs = try allocator.alloc(Structtest_Inner3, v.len());
                for (0..v.len()) |i| {
                    if (v.at(i)) |item| {
                        if (item.asMessage()) |sub| {
                            xs[i] = try Structtest_Inner3.load(allocator, schema, &sub, sty);
                        }
                    }
                }
                out.inners = xs;
            }
        }
        {
            const f = try ty.field("opt_i32");
            if (msg.has(f)) { out.opt_i32 = @as(i32, @truncate(msg.getI64(f))); }
        }
        {
            const f = try ty.field("opt_str");
            if (msg.has(f)) { out.opt_str = (if (msg.getStr(f)) |s| try allocator.dupe(u8, s) else ""); }
        }
        {
            const f = try ty.field("flags");
            if (msg.value(f)) |v| {
                var xs = try allocator.alloc(bool, v.len());
                for (0..v.len()) |i| {
                    if (v.at(i)) |item| {
                        xs[i] = item.asBool();
                    }
                }
                out.flags = xs;
            }
        }
        return out;
    }
